insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 1, 'What are the two questions this course asks?', '["How to run a gun, and how to place a gravel pack.", "What a perforation does to the flow, and what the sand does to the completion.", "How much oil a well will produce, and how long the completion hardware installed in it can be expected to last.", "Which charge a vendor should be asked for, and what the surface facilities will need to handle the produced solids."]'::jsonb, 1, 'They meet at the perforation, which is both the flow path and the cavity whose wall either holds or fails.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 2, 'Why are perforating and sand control taught as one subject?', '["Because the tunnel a charge makes is the same cavity the sanding calculation is about.", "Because both are done on the same wireline run.", "Because the two calculations share an input file format, which makes it convenient to present them together in one tool.", "Because sand control equipment is always installed at the same time as the perforating gun is run into the well."]'::jsonb, 0, 'And a gravel pack is perforated with a different gun, because the pack has to be placed through the holes.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 3, 'What does a shaped charge actually do to the rock?', '["It burns a hole through the casing and cement.", "It generates a pressure pulse that fractures the formation radially outward from the wellbore over a short interval.", "A metal jet at several kilometres a second punches a tunnel hydrodynamically.", "It drills a hole mechanically using a small rotating bit deployed from the carrier once the gun is at depth."]'::jsonb, 2, 'At those velocities steel and rock behave more like very stiff fluids than like solids.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 4, 'What is left behind after a charge fires?', '["A clean cylindrical hole with no damage at all.", "A fracture propagating from the wellbore into the formation, whose length is set by the explosive weight of the charge.", "A cavity filled with the residue of the liner, which has to be removed by acid before the well can be flowed.", "A tapering tunnel, a hole through the casing, and a shell of crushed rock around the tunnel."]'::jsonb, 3, 'The crushed shell is one of the four skin components the next tier computes.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 5, 'Which four dimensions does the rest of the course reduce a perforation to?', '["Tunnel length, tunnel radius, shot spacing and wellbore radius.", "Entrance hole, exit hole, taper angle and depth.", "Charge weight, liner material, standoff from the casing wall and the strength of the concrete target it was measured in.", "Casing size, cement thickness, formation porosity and the absolute permeability of the rock the tunnel reaches into."]'::jsonb, 0, 'Not the taper, not the tip shape and not the roughness of the tunnel wall.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 6, 'By which two mechanisms does sand arrive at surface?', '["Erosion of the casing and corrosion of the tubing.", "Loose fines migrating with the flow, and mechanical failure of the cavity wall.", "Dissolution of the cement behind the casing, and the collapse of the gravel pack once its screen has eroded through.", "Precipitation of scale from the produced water, and the breakdown of the formation by acid during a stimulation job."]'::jsonb, 1, 'The second is what the Expert tier computes; the first is what the fines percentage warns about.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 7, 'Which of these is a well integrity failure rather than a production problem?', '["A separator full of sand at surface.", "An eroded choke, which reduces the rate the well can deliver until it is replaced at the next opportunity.", "A safety valve cut out by sand.", "A filled rathole, which costs deferred production until a cleanout can be scheduled and run on the well."]'::jsonb, 2, 'The others cost money and production. A cut-out safety valve is a barrier that no longer works.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 8, 'What are the three answers to a sand-producing reservoir?', '["Gravel pack, frac pack or standalone screen.", "Reperforate with a bigger gun, acidise the near-wellbore region, or squeeze the perforations with resin to consolidate them.", "Produce the well slowly, produce it fast enough to carry the sand out, or shut it in until the reservoir depletes.", "Manage it at surface, screen it out, or keep the drawdown below the failure point."]'::jsonb, 3, 'The third costs rate, and an operator may still choose it over the cost of hardware.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 9, 'Which of these does this engine compute?', '["A critical flowing pressure from a Kirsch hoop stress along a perforated interval.", "A production rate from a reservoir model.", "The penetration a given shaped charge will achieve in a formation of stated strength at a stated effective stress.", "How much sand a failing cavity will produce, in grams per cubic metre, over the producing life of the well."]'::jsonb, 0, 'It computes an onset criterion, and it computes no rate of anything.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 10, 'Why does the productivity ratio need no permeability?', '["Because permeability is assumed to be one millidarcy.", "Because it compares two geometries at the same everything else, so the permeability cancels.", "Because the ratio is computed at a reference condition and then corrected for permeability outside the engine itself.", "Because the correlation was developed on a single reservoir whose permeability was measured and is built into the constants."]'::jsonb, 1, 'A rate would need it. A ratio against an ideal at the same conditions does not.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 11, 'What does the engine do when a dimensionless group leaves the correlation''s development range?', '["Refuses the calculation entirely.", "Clamps the group to the edge of the range and returns the value at the edge, which is the closest supported answer.", "Returns the number and attaches a warning naming the group and the value.", "Extrapolates the fit and returns the number silently, since the expression evaluates perfectly well outside the range."]'::jsonb, 2, 'The input is a legitimate description of a real gun, and the reader may have no alternative.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 12, 'Somebody enters a thirty degree phasing. What happens, and why?', '["A gun whose total skin comes out positive.", "A dimensionless perforation radius above the upper end of the range the correlation was developed over.", "A sieve curve whose finest sieve stops short of the ninety fifth percentile of the sample by weight.", "A phasing angle that is not one of the six in the published tables."]'::jsonb, 3, 'A positive skin is a result, an out-of-range group is a warning, and a short sieve returns nulls.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 13, 'Why is a perforation reduced to four lengths rather than modelled in full?', '["Because the flow resistance of that geometry depends on those four and little else.", "Because the full geometry is not measurable.", "Because the correlation was fitted before computers could handle a full three dimensional model of a tapering cavity.", "Because the taper and the tip shape vary so much between charges that including them would make the answer meaningless."]'::jsonb, 0, 'Fluid converges from the reservoir into small cylinders spaced along a large one, and that is what the four describe.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 14, 'What does a sieve analysis measure, and in what units?', '["The distribution of grain sizes, by grain count.", "The distribution of grain sizes, as cumulative percentages by weight.", "The permeability of the sample at each of several confining pressures, reported as a fraction of the unstressed value.", "The mineral composition of the sample, reported as the weight fraction of each mineral present in the formation."]'::jsonb, 1, 'By weight matters: a few percent of fines by weight is an overwhelming majority by count.'),
  ('perfsand', 'beginner', 'module', 'm01-what-this-course-decides', 15, 'What is the Associate tier about?', '["Computing the perforation skin and the productivity ratio.", "Choosing between the five completion types and sizing the gravel and the screen that follow from that choice.", "Reading the two inputs honestly: what a charge leaves, and what a sand sample says.", "Deciding the maximum drawdown a perforated interval can carry before the cavity wall begins to fail mechanically."]'::jsonb, 2, 'Get either input wrong and everything downstream is confidently wrong.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 1, 'Why does the penetration of a shaped charge depend on the target material?', '["Because harder targets blunt the jet more quickly.", "Because the explosive burns at a different rate depending on the acoustic impedance of the material it is fired against.", "Because the jet penetrates hydrodynamically, so density rather than strength governs.", "Because the standoff between the charge and the target changes with the material, which changes where the jet forms."]'::jsonb, 2, 'At jet tip velocities the strength of the target is negligible against the stagnation pressure.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 2, 'Why can one charge not maximise both entrance hole and penetration?', '["Because a concentrated jet penetrates deep and a spread one makes a wide hole.", "Because the explosive weight is fixed by the carrier size.", "Because the two are measured in different targets, so a charge optimised for one cannot be tested against the other.", "Because a wide entrance hole requires a slower jet, and a slow jet cannot travel far enough to reach the formation."]'::jsonb, 0, 'Which is why the catalog shows the trade in every row and why big-hole charges exist as a family.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 3, 'The skin calculation needs a tunnel radius. Where does it come from?', '["The full entrance hole diameter.", "Half the entrance hole diameter, as a stand-in for a tapering shape.", "The average of the entrance hole radius and the tip radius, weighted by the length over which each of them applies.", "The radius measured at the mid-point of the tunnel, which the vendor reports separately from the entrance hole figure."]'::jsonb, 1, 'It is an approximation and the correlation was fitted with that convention.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 4, 'What correction does the published penetration need before it becomes the tunnel length?', '["It has to be doubled to give a diameter.", "It has to be divided by the shot density, because the published figure is the total penetration of the whole gun run.", "It has to be multiplied by the phasing constant, which converts a nominal penetration into an effective one.", "It has to be reduced by the cement sheath, because the flow calculation wants the length in the formation."]'::jsonb, 3, 'And a formation figure is generally less than a concrete figure at the same charge.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 5, 'In what units is shot density quoted, and what does the calculation use?', '["Quoted per foot; the calculation uses the spacing, which is the reciprocal of the density.", "Quoted per metre and used per metre.", "Quoted per foot and used per foot, with the conversion to metric applied only when the result is displayed to the user.", "Quoted as a total number of shots and converted to a density by dividing by the length of the perforated interval."]'::jsonb, 0, 'Doubling the density does not double anything; it halves the spacing, and the spacing is what enters.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 6, 'Why does the calculation use the spacing rather than the density?', '["Because the spacing is easier to measure on a gun.", "Because the flow has to converge vertically, and the spacing is how far it must travel.", "Because the density is quoted per foot and the spacing is already in metres, which avoids a unit conversion in the engine.", "Because the correlation was fitted against spacing, and refitting it against density would change the tabulated constants."]'::jsonb, 1, 'Halve the spacing and each perforation drains a shorter interval, so the converging skin falls.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 7, 'Why does the return on extra shots per foot diminish?', '["Because the gun cannot carry more than twelve charges per foot.", "Because the casing is weakened by each additional shot, so beyond a point the extra holes have to be traded against strength.", "Because the spacing is a reciprocal, so equal steps in density are unequal steps in spacing.", "Because the converging-flow term saturates at a fixed value once the spacing falls below the tunnel radius."]'::jsonb, 2, 'Four to eight halves the spacing; eight to twelve only takes another third off it.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 8, 'What is phasing?', '["The delay between successive charges firing.", "The angle between the gun axis and the wellbore axis, which depends on how the gun is centralised in the casing.", "The orientation of the whole gun relative to the maximum horizontal stress, set by an orienting sub above the carrier.", "The angle by which each successive shot is rotated around the gun axis from the one before."]'::jsonb, 3, 'A ninety degree gun puts shots at four compass points in rotation.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 9, 'Give two reasons a gun is phased at all.', '["Symmetric drainage converges more easily, and spreading the shots spreads the casing damage.", "It is cheaper and it is easier to manufacture.", "It allows a higher shot density in the same carrier length, and it reduces the shock transmitted to the cement sheath.", "It lets the gun be run without orientation, and it makes the entrance holes easier to find on a subsequent log."]'::jsonb, 0, 'Perforations all on one side drain a quarter of the rock badly and three quarters of it worse.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 10, 'What is different about zero phasing?', '["It is simply the smallest angle in the table.", "It uses a different formula, in which the wellbore radius drops out entirely.", "It fires all the charges simultaneously rather than in sequence, which changes the shock loading on the casing string.", "It uses the same formula with a constant of zero, which makes the effective wellbore radius vanish and the skin infinite."]'::jsonb, 1, 'The effective wellbore radius becomes a quarter of the tunnel length rather than a constant times a sum.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 11, 'Which six phasing angles do the published tables carry?', '["Every angle from zero to three hundred and sixty.", "Zero, thirty, sixty, ninety, a hundred and twenty and a hundred and eighty, which are the common commercial gun phasings.", "Zero, forty five, sixty, ninety, a hundred and twenty and a hundred and eighty degrees.", "Forty five, sixty, ninety, a hundred and twenty, a hundred and eighty and three hundred and sixty degrees."]'::jsonb, 2, 'The engine refuses anything else rather than interpolating between two fitted constant sets.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 12, 'What does an API Section One test measure, and where?', '["Penetration in the formation at reservoir conditions.", "The pressure pulse the charge generates in the wellbore fluid, measured against a standard casing and cement arrangement.", "The consistency of the charge from batch to batch, measured by firing a sample from each production lot into steel plate.", "Entrance hole and total penetration, in a concrete target at surface."]'::jsonb, 3, 'It is a comparison standard: it lets two vendors'' charges be compared on equal terms.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 13, 'Which parts of the gun catalog transfer to a real vendor''s data?', '["The structure: small guns are in line and low density, big-hole charges trade depth for width.", "The specific entrance holes and penetrations.", "Nothing at all, since every vendor uses a different charge design and no comparison between catalogs is meaningful.", "The shot densities and phasings, which are standardised across the industry, but not the entrance holes or penetrations."]'::jsonb, 0, 'Those relationships follow from the physics of the charge and the size of the carrier.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 14, 'Which correction does this engine deliberately NOT apply?', '["Converting shots per foot into shots per metre.", "Converting an API concrete penetration into an expected formation penetration.", "Halving the entrance hole diameter to get the tunnel radius used by the plane-flow and converging-flow terms.", "Applying the phasing constant to the sum of the wellbore radius and the tunnel length in the effective radius."]'::jsonb, 1, 'It is stated so the reader can apply it outside the tool rather than assume it was applied inside.'),
  ('perfsand', 'beginner', 'module', 'm02-the-shot', 15, 'What may the catalog be used for?', '["Ordering a gun from a vendor.", "Promising a client a penetration in a given formation, provided the concrete figure is corrected for the rock strength.", "Learning the method and comparing gun classes against each other.", "Arguing with a vendor whose quoted entrance hole differs from the value in the corresponding catalog row."]'::jsonb, 2, 'Every row is flagged approximate precisely so that the other three cannot happen by accident.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 1, 'How many inputs does the skin calculation take in total?', '["Four, one for each of the four components.", "Seven: four lengths, one angle and two permeability ratios.", "Twelve, which is the number of catalog fields a gun row carries once the conveyance and the notes are included.", "Nine, the seven geometric ones plus the drainage radius and the absolute permeability of the reservoir rock."]'::jsonb, 1, 'The drainage radius belongs to the productivity ratio, and the absolute permeability appears nowhere.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 2, 'Which of these is NOT an input to the skin calculation?', '["The gun standoff from the casing wall.", "The wellbore radius.", "The ratio of the horizontal permeability to the vertical permeability, which enters the converging-flow term twice.", "The ratio of the undamaged permeability to the crushed-zone permeability, which scales the crushed-zone term."]'::jsonb, 0, 'Standoff is real, it is significant, and this model has no input for it.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 3, 'Why does the absence of a perforated interval length matter?', '["Because it makes the calculation depend on the well depth.", "Because the correlation needs the interval length to compute the number of shots, which sets the total flow area available.", "Because the skin is per unit length and assumes the whole interval is perforated the same way.", "Because a longer interval means a larger drainage radius, and the productivity ratio depends on the drainage radius."]'::jsonb, 2, 'A partially perforated interval has a partial penetration skin on top, which is a different calculation.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 4, 'Convert six shots per foot into a spacing in metres.', '["A little over six centimetres.", "About twenty centimetres, which is the reciprocal of the density expressed in shots per metre rather than per foot.", "About two and a half centimetres, which is the spacing a twelve shot per foot gun would give instead.", "A little over five centimetres."]'::jsonb, 3, 'A foot divided by six. Twice the density always gives half the spacing, which is the only shape this conversion has.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 5, 'Name the three places the perforation spacing enters the skin calculation.', '["The dimensionless spacing, the dimensionless perforation radius, and the crushed-zone factor.", "The plane-flow term and the blockage term only.", "The effective wellbore radius, the dimensionless spacing and the exponent of the converging-flow power law expression.", "The crushed-zone term only, where it appears as a ratio against the length of the perforation tunnel itself."]'::jsonb, 0, 'It touches neither the plane-flow term nor the blockage term, which is why density is a two-component lever.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 6, 'What check catches a shot density used in the wrong units?', '["The spacing must be less than the tunnel length.", "Spacing times density must equal one exactly, in the same units.", "The dimensionless spacing must fall inside the range the correlation was developed over, which is up to about ten.", "The total skin must come out negative, since a correctly converted density always gives a stimulating completion."]'::jsonb, 1, 'The error is a factor of about three and a quarter in a term that matters.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 7, 'What is the effective wellbore radius?', '["The radius of the perforation tunnel.", "The radius at which the pressure equals the average reservoir pressure, which the productivity ratio compares against.", "The radius of an unperforated well that would flow the same as this perforated one.", "The radius of the crushed zone around the tunnel, measured from the tunnel axis rather than from the wellbore axis."]'::jsonb, 2, 'Far from the well, a perforated completion looks exactly like radial flow into a plain cylinder.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 8, 'What does a negative plane-flow skin mean physically?', '["The calculation has produced an impossible result.", "The crushed zone has a higher permeability than the formation, which can happen when the jet fractures the rock finely.", "The wellbore radius is smaller than the tunnel radius, which reverses the sign of the logarithm in the expression.", "The perforations make the well behave as though it were larger than it was drilled."]'::jsonb, 3, 'The tunnels are fingers of high conductivity reaching into rock an open hole of the same radius never touches.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 9, 'Which phasing angle gives the largest effective wellbore radius?', '["Forty five degrees, because its tabulated constant is the largest of the phased angles.", "A hundred and eighty degrees.", "Ninety degrees, because four shots around the circumference give the most symmetric drainage of any available angle.", "Zero degrees, because the in-line formula uses the tunnel length directly rather than scaling it by a constant."]'::jsonb, 0, 'The constant falls monotonically above zero, so more spread is worse rather than better.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 10, 'What is the crushed zone?', '["The volume of rock removed by the jet.", "A shell of compacted and fractured rock around the tunnel, with reduced permeability.", "The zone of the casing immediately around the entrance hole, where the steel has been deformed by the passage of the jet.", "The region of the formation into which charge debris has been driven, extending several tunnel diameters into the rock."]'::jsonb, 1, 'Typically a few millimetres to a centimetre thick, worst at the wall and fading outward.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 11, 'What are the three factors of the crushed-zone skin?', '["The tunnel radius, the crushed radius and the permeability.", "The shot density, the phasing constant and the difference between the undamaged and the damaged permeabilities.", "Spacing over tunnel length, the log of the radius ratio, and the contrast less one.", "The wellbore radius over the tunnel length, the crushed radius squared, and the ratio of the two permeabilities."]'::jsonb, 2, 'Zero when the contrast is one, linear in the contrast less one, and logarithmic in the shell thickness.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 12, 'Why is the crushed zone the only removable skin component?', '["Because it is the smallest of the four components.", "Because it is the only one that depends on the shot density, which can be increased by running a second gun over the same interval.", "Because it disappears once the well has been produced long enough for the near-wellbore pressure to equalise.", "Because it is a permeability contrast, and permeability can be restored."]'::jsonb, 3, 'Underbalanced perforating, an acid wash and a surge tool all attack it; the geometry is fixed once the gun has fired.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 13, 'Why does the engine refuse a crushed-zone permeability ratio below one?', '["Because it would give a negative crushed-zone skin, which is not an outcome of shooting a hole.", "Because the logarithm would be undefined.", "Because a ratio below one means the crushed radius is smaller than the tunnel radius, which is caught by a different check.", "Because the correlation was fitted only for ratios above one, so a smaller value would be an extrapolation of the fit."]'::jsonb, 0, 'Returning it would make a damaged completion look stimulated.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 14, 'Which of these does the engine refuse rather than warn about?', '["A dimensionless spacing above ten.", "A shot density of zero.", "A dimensionless perforation radius above the upper end of the range the correlation was developed against.", "A gun whose total skin comes out positive, since a positive skin means the perforating has damaged the well."]'::jsonb, 1, 'A zero density is no perforating, and it would divide by zero downstream.'),
  ('perfsand', 'beginner', 'module', 'm03-the-geometry-the-charge-leaves', 15, 'What is the test for whether an input should be refused rather than warned about?', '["Whether the arithmetic survives it.", "Whether the value falls inside the range over which the underlying correlation was originally developed and fitted.", "Whether a reader could tell from the output that something was wrong.", "Whether the input is physically possible in a real well, as opposed to merely being unusual or badly chosen."]'::jsonb, 2, 'Every one of the eight refusals would otherwise produce a believable number.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 1, 'Describe the sieve measurement.', '["A dried sample is passed through a stack of sieves and what each one retains is weighed.", "A sample is imaged and the grains are counted.", "A sample is suspended in a fluid and the settling velocity of each fraction is measured against Stokes law over time.", "A sample is compressed in a cell and the pore throat size distribution is measured by mercury injection at rising pressure."]'::jsonb, 0, 'The output is a table of cumulative percentage retained at or above each sieve opening.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 2, 'Which sample source is the most biased, and why?', '["Whole core, because it is taken under mud pressure.", "Produced sand caught at surface, because it is what the formation was willing to give up.", "Sidewall core, because the percussion or rotary process that takes it breaks grains and creates fines that were not there.", "All three are equally biased, because none of them is taken at the flowing condition the completion will experience."]'::jsonb, 1, 'Every source has a bias and the produced one is the worst.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 3, 'What are sieve percentages a percentage of?', '["The volume of the sample.", "The number of grains, which is why a small fines percentage still represents very few particles in absolute terms.", "The weight of the sample, not the number of grains in it.", "The pore volume of the sample, measured before the sample was disaggregated for the sieve analysis to be run."]'::jsonb, 2, 'A sample with a few percent fines by weight has an enormous number of fine grains.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 4, 'Give the two separate reasons sizes are handled on a log scale.', '["Because the numbers are small and awkward to plot.", "Because the sieve openings are quoted in microns while the calculation works in metres, and the conversion is a power of ten.", "Because a log scale compresses the coarse end, where the sieve data are least reliable and the sample mass is smallest.", "Sieve series step by a constant ratio, and natural grain distributions are log-normal."]'::jsonb, 3, 'The first makes the axis sensible and the second makes the curve nearly straight.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 5, 'Which convention does this course use for a grain size curve?', '["Cumulative percent retained, which falls as the size rises.", "Cumulative percent passing, which rises as size rises.", "Percent retained on each individual sieve, without accumulating, which gives a histogram rather than a cumulative curve.", "Cumulative percent passing for the coarse half of the curve and cumulative percent retained for the fine half."]'::jsonb, 0, 'Soil mechanics uses passing. A reader arriving from there reads every number backwards.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 6, 'Which D-value is the same in both conventions, and why?', '["D10, because it is the coarse decile in both.", "D50, because fifty is its own complement.", "D90, because ninety percent of the sample is on the same side of it whichever way the curve is accumulated.", "None of them, because the two conventions accumulate from opposite ends of the size distribution entirely."]'::jsonb, 1, 'Everything else flips, and D10 is the coarse decile on a retained curve.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 7, 'What is the check that catches a passing curve read as a retained one?', '["The percentages must sum to a hundred.", "The uniformity coefficient must be greater than one, since the fortieth percentile is always coarser than the ninetieth.", "D10 must be larger than D50, which must be larger than D90.", "The finest sieve must retain more than the coarsest one, which is true of any correctly ordered cumulative curve."]'::jsonb, 2, 'If your D10 is the smallest number in the table, one of the two conventions has been misread.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 8, 'Why did sand control adopt the retained convention?', '["Because it was the first convention published.", "Because a retained curve is easier to compute from the raw sieve weights, which are recorded as what stayed on each sieve.", "Because the fine end of a distribution cannot be measured reliably, so a convention starting from the coarse end is safer.", "Because its design questions are about the coarse end, which the convention puts at low D numbers."]'::jsonb, 3, 'A gravel is sized on the median and a standalone slot on the coarse decile.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 9, 'What is D50 used for in this course?', '["Sizing a standalone screen slot.", "Computing the uniformity coefficient, which is the ratio of the fortieth percentile to the ninetieth on the retained curve.", "Sizing the gravel, at five to six times the formation median.", "Deciding the completion type, since the ladder reads the median together with the fines percentage."]'::jsonb, 2, 'The coarse decile sizes a standalone slot, and neither of them decides the completion type.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 10, 'Why does the engine compute six D-values when it strictly needs two?', '["Because six percentiles across the range show the shape, and the shape is what the summaries measure.", "Because six is the number of sieves in a standard stack.", "Because the four extra values are needed to interpolate the two that matter, which fall between the measured sieve points.", "Because each of the six is used by a different published sizing rule, and the engine supports all six of those rules."]'::jsonb, 0, 'And a curve that cannot reach some of them says something worth knowing.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 11, 'Two sieves a decade apart bracket the fiftieth percentile at forty and sixty percent retained. What is D50?', '["The arithmetic mean of the two sizes.", "The geometric mean of the two sizes, which is smaller than their arithmetic mean.", "The larger of the two sizes, since the engine takes the coarser bracketing point when the percentile falls between two sieves.", "It cannot be determined without a third point, because two points cannot define a curve through the fiftieth percentile."]'::jsonb, 1, 'A decade apart, the arithmetic mean is about one point seven times the geometric one, which is a size class.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 12, 'Which way does a linearly interpolated D-value err, and what does that cost?', '["It understates the size, which plugs the pack.", "It errs in either direction depending on which side of the bracketing pair the percentile falls, so the bias averages out.", "It has no systematic bias, but its scatter is larger, which widens the uncertainty on every downstream decision.", "It overstates the size, which sizes the gravel too coarse and lets formation sand through."]'::jsonb, 3, 'And the error is largest where the sieves are furthest apart, which is where the data are weakest anyway.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 13, 'What does the engine return for a D-value the curve does not reach?', '["Null, because zero and the finest sieve size are both wrong in ways that propagate.", "Zero.", "The size of the finest sieve in the stack, which is a real measurement and therefore the best available lower bound.", "An extrapolated value from the last two points, flagged so that a reader can see it was not measured directly."]'::jsonb, 0, 'Null is the only answer that cannot be mistaken for a result.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 14, 'A sieve stack stops at seventy percent retained. Trace the consequence.', '["No D50, so no gravel can be sized at all.", "No D90, so no uniformity, so the advisor returns insufficient coverage rather than a rung.", "No fines percentage, since the fines cutoff sits below the finest sieve and the engine will not extrapolate to reach it.", "No effect, because the advisor reads the median and the fines and neither of those needs the ninetieth percentile."]'::jsonb, 1, 'One missing measurement propagates all the way to the recommendation and stops it.'),
  ('perfsand', 'beginner', 'module', 'm04-the-sand-sample', 15, 'Why does the fines percentage behave differently from a percentile?', '["Because fines are measured by a different method.", "Because the fines cutoff is a convention rather than a measurement, so the engine is entitled to extrapolate towards it.", "Because a fraction at a fixed size can be read off the end of the curve; a percentile needs the curve to reach it.", "Because the fines percentage is reported as a complement, and a complement is defined even where the curve is absent."]'::jsonb, 2, 'If the whole curve is coarser than the cutoff, the fines are whatever is finer than the finest sieve, which is a real bound.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 1, 'Define the uniformity coefficient used in this course.', '["The ninetieth divided by the fortieth.", "The fortieth percentile divided by the ninetieth, on the retained curve.", "The coarse decile divided by the fine twentieth, which spans a much wider part of the distribution than the middle does.", "The median divided by the ninetieth, which measures how far the fine half of the sample spreads below its centre."]'::jsonb, 1, 'It is always greater than one, because the fortieth percentile is coarser than the ninetieth on a retained curve.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 2, 'What does the uniformity measure?', '["The width of the middle of the distribution, not its full range.", "The absolute grain size of the sample.", "The spread of the tails, which is what decides whether fine material can travel through a bridge once one has formed.", "The shape of the distribution, in the sense of whether it is symmetric or skewed towards the coarse or the fine end."]'::jsonb, 0, 'The sorting coefficient covers the full range, and it is dominated by the tails.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 3, 'Explain the bridging mechanism a screen relies on.', '["The screen filters every grain larger than its slot.", "The fluid velocity through the slot is high enough to keep grains suspended, so they pass through rather than accumulating.", "Grains too large to pass an opening arrest at it and form an arch that holds finer material back.", "The grains are held electrostatically against the wire, which builds a filter cake whose permeability is set by the fines."]'::jsonb, 2, 'Which is why the sizing rules are ratios, and why a poorly sorted sand defeats them.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 4, 'Why does a poorly sorted sand defeat bridging?', '["Because there are no coarse grains to form the bridge.", "Because the grains are angular rather than rounded, so they cannot pack closely enough to form a stable arch across the slot.", "Because the bridge collapses under the drawdown, and a wider distribution collapses at a lower drawdown than a narrow one.", "Because the fine tail passes through the bridge and keeps going."]'::jsonb, 3, 'The well produces fines forever through a screen that is technically doing its job.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 5, 'What are the two uniformity thresholds on the ladder?', '["Three and five.", "Two and ten.", "One and a half and six, which are the values the published selection literature quotes for wire-wrap and premium screens.", "Two, five and ten, which are also the three thresholds the fines percentage uses in the same ladder."]'::jsonb, 0, 'Below three is uniform enough for a wire-wrap screen if the fines are also low; below five for a premium one.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 6, 'Define the sorting coefficient and say how it differs from the uniformity.', '["The same ratio computed on a passing curve.", "The coarse decile over the fine twentieth, so it is dominated by the tails rather than the middle.", "The median over the ninetieth percentile, which measures the fine half of the distribution rather than the whole of it.", "The standard deviation of the grain size distribution divided by its mean, expressed as a dimensionless coefficient."]'::jsonb, 1, 'Two sands can share a uniformity and differ enormously in sorting.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 7, 'Why does the ladder not decide on the sorting coefficient?', '["Because the sorting is redundant with the uniformity.", "Because the sorting cannot be computed from a standard sieve stack, which rarely extends to the ninety fifth percentile.", "Because the tails are where a sieve analysis is least reliable.", "Because the published selection literature was written before the sorting coefficient came into common use in the industry."]'::jsonb, 2, 'The coarse end has very little material on it and the fine end depends on where the stack stopped.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 8, 'What is a large gap between the uniformity and the sorting telling you?', '["That the sieve analysis has been done incorrectly.", "That the sand is bimodal, with two distinct populations of grain size and very little material between the two of them.", "That the sample has been contaminated with drilling solids, which broaden both tails without changing the middle.", "That the distribution has tails the uniformity is not describing."]'::jsonb, 3, 'And it tells you to look at the fines number carefully, which is exactly where the published sand lands.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 9, 'Where is the fines cutoff and what is it?', '["Forty four microns, which is a three hundred and twenty five mesh opening and a convention.", "Two microns, the conventional clay size boundary.", "One tenth of the median grain size of the sample, so that the definition scales with the sand rather than being fixed.", "The opening of the finest sieve in the stack, whichever that happens to be for the analysis being reported."]'::jsonb, 0, 'Nothing changes about a grain at forty three microns that does not change at forty five.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 10, 'Why do fines plug a pack rather than bridging on its face?', '["Because they are chemically reactive.", "Because they are fine enough to enter the pack and lodge in the pore throats inside it.", "Because they arrive first, before the coarse grains, and coat the face of the pack in a layer of very low permeability.", "Because they are carried at a higher velocity than the coarse grains and therefore strike the pack with more energy."]'::jsonb, 1, 'A pack that has plugged is worse than no pack, because the drawdown needed to produce through it rises.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 11, 'Why is five percent fines by weight a much larger number by count?', '["Because the sieve overestimates the fine fraction.", "Because the fines are measured on a different sample from the coarse fraction, and the two are combined by a conversion factor.", "Because fine grains are light, so a small mass fraction is a very large number of particles.", "Because the count is reported per unit volume while the weight is reported per unit mass, and the densities differ."]'::jsonb, 2, 'At a tenth of the diameter there are roughly a thousand times as many grains per unit mass.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 12, 'At which fines percentages does the ladder step down a rung?', '["Three and five percent.", "One, five and twenty percent, matching the wire-wrap, premium screen and gravel pack rungs of the selection ladder.", "Five and ten percent, which are the only two the ladder uses since the first rung is decided on uniformity alone.", "Two, five and ten percent."]'::jsonb, 3, 'The published sand sits between five and ten, which puts it on the gravel pack rung.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 13, 'What does a fines percentage NOT tell you?', '["What the fines are made of, which changes whether they migrate or swell.", "How much of the sample is below the cutoff.", "Whether the fines were present in the formation or were created by the coring process that recovered the sample.", "Whether the sample is representative of the interval, since one sieve analysis describes one depth in one well."]'::jsonb, 0, 'Forty four microns of quartz is inert; the same size of smectite swells when the salinity changes.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 14, 'Why does the ladder read two numbers rather than three?', '["Because a third number would be too expensive to measure.", "Because they describe the two independent ways a screen fails.", "Because the median grain size is already implied by the uniformity and the fines, so adding it would be redundant information.", "Because the published selection literature only reports two, and the engine reproduces the published rule exactly."]'::jsonb, 1, 'A sand that is not uniform defeats bridging; a sand with a lot of fines plugs whatever bridges.'),
  ('perfsand', 'beginner', 'module', 'm05-uniformity-and-fines', 15, 'Why does the median grain size not appear in the ladder?', '["Because it is unreliable in a short sieve stack.", "Because a screen can only be manufactured in a handful of standard slot widths, so the median is rounded away in any case.", "Because it sets the SIZE of the screen or gravel, not the TYPE of completion.", "Because the median is the same for a well sorted and a poorly sorted sand, which makes it useless for any decision."]'::jsonb, 2, 'A coarse uniform clean sand and a fine uniform clean sand get the same indication.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 1, 'A colleague asks what an Associate pass in this course lets you do. What is the honest reply?', '["Design a perforating job and a sand control completion.", "Compute the perforation skin and the productivity ratio for any gun in the catalog against any reservoir anisotropy.", "Read a gun catalog and a sieve table, and compute the geometry and the statistics from each.", "Decide whether a well needs sand control, and size the gravel and the screen that would be run if it did."]'::jsonb, 2, 'Not yet what any of it does to the flow, and not yet which gravel or screen follows.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 2, 'One idea holds both halves of this tier together. Which is it?', '["Both halves are about reading an input honestly before anything is computed from it.", "Both halves reduce to four lengths.", "Both halves depend on the permeability of the reservoir, which enters the skin calculation and the underbalance guidance alike.", "Both halves are screening grade, so neither can support a design decision without laboratory confirmation first."]'::jsonb, 0, 'A charge data sheet is a measurement in the wrong material and a sieve curve is on a reversed convention.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 3, 'A gun data sheet quotes a penetration of two feet. What do you need before using it?', '["The shot density of the gun.", "The phasing angle, since the effective wellbore radius formula differs between in-line and phased guns and needs the angle.", "The wellbore radius, which is subtracted from the penetration to give the length of tunnel inside the formation.", "The target it was measured in, and the cement thickness to subtract."]'::jsonb, 3, 'An API concrete figure is not a formation figure, and the flow calculation wants the length beyond the cement.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A tally quotes six shots per foot. What number does the calculation use?', '["Six, converted to shots per metre.", "The spacing, which is a foot divided by six.", "Six times the length of the perforated interval in feet, which gives the total number of shots the gun will fire.", "The reciprocal of six, in feet, which is the spacing without any conversion into metres being applied to it."]'::jsonb, 1, 'Everything downstream is metric, and the spacing rather than the density is what enters.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 5, 'A sieve table arrives with D10 as the smallest number in it. What do you conclude?', '["It is a passing curve, or the two conventions have been mixed.", "It is a very well sorted sand.", "The sieve stack was too short at the coarse end, so the coarse decile has been extrapolated rather than interpolated.", "Nothing is wrong: D10 is the fine decile on a retained curve and is expected to be the smallest of the D-values."]'::jsonb, 0, 'On a retained curve D10 is the coarse decile and is the largest of the D-values.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 6, 'A completion engineer proposes a wire-wrap screen on a sand with eight percent fines. What do you say?', '["It is fine, because eight is below ten.", "It depends on the median grain size, since a coarse sand tolerates more fines than a fine one at the same uniformity.", "The fines alone rule it out, whatever the uniformity is.", "It is fine provided the uniformity is below three, because the two conditions on that rung are independent of each other."]'::jsonb, 2, 'The wire-wrap rung needs fines below two percent AND uniformity below three, and both have to hold.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 7, 'You are handed a D50 and asked for the gravel band. What else do you need?', '["The uniformity coefficient and the fines percentage.", "The coarse decile as well, since the band is bounded below by the median and above by a fraction of the coarse decile.", "The screen gauge, because the gravel has to be coarse enough that the chosen gauge will retain it in the annulus.", "Nothing; the band is five to six times the median."]'::jsonb, 3, 'One input, one output. The screen comes afterwards and from the gravel rather than from the sand.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Which single scan on a gun catalog predicts which rows will damage a well?', '["The penetration column, shortest first.", "The phasing column: the in-line rows are the ones with positive skin.", "The carrier outside diameter column, since the catalog ranks monotonically by gun size and the smallest guns are the worst.", "The shot density column, since the two rows at four shots per foot are the two whose converging-flow term is largest."]'::jsonb, 1, 'All three correlate in this catalog. Phasing is the one that changes the formula rather than a value.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 9, 'A sieve stack stops at a hundred microns. Which decisions can still be made?', '["All of them, since the median is available.", "None of them, because the fines percentage is unavailable and every decision in this course depends on the fines.", "The median and the gravel band, but not the uniformity or the completion type.", "Only the standalone slot window, which needs the coarse decile and is unaffected by where the stack stops at the fine end."]'::jsonb, 2, 'No D90 means no uniformity, and the advisor returns insufficient coverage rather than a rung.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Somebody quotes a penetration from this course''s catalog in a design document. What is wrong?', '["Every row is flagged approximate and is a published-typical value rather than a vendor figure.", "Nothing, provided the gun class is stated.", "The figure needs to be converted from inches to metres first, since design documents are written in SI units throughout.", "The figure is a total penetration and the document needs the formation penetration, which is a different number entirely."]'::jsonb, 0, 'The catalog is for learning the method and comparing classes, not for ordering hardware.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Why is the crushed zone the component a designer can still attack after choosing the gun?', '["Because it is the largest of the four components.", "Because it is a permeability contrast rather than a geometry, and permeability can be restored.", "Because it depends on the shot density, which can be raised by running a second gun over the same interval afterwards.", "Because it is proportional to the tunnel length, which grows as the well produces and the near-wellbore rock erodes."]'::jsonb, 1, 'Underbalanced perforating, an acid wash and a surge tool all attack it.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 12, 'A sand has a uniformity of two and fines of one percent. What does the ladder say and why?', '["A gravel pack, because it satisfies the third rule.", "Nothing, because a sand this clean does not need sand control at all and the ladder has no rung for a natural completion.", "A premium screen, because the wire-wrap rung requires the fines below two percent and one percent is too close to the limit.", "A wire-wrap screen, because it is the first rung whose two conditions both hold."]'::jsonb, 3, 'The rules overlap and the ladder returns the first match, which is the least intervention that works.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What is the single most useful check on a shot density conversion?', '["Multiply the spacing by the density in the same units and confirm it is one.", "Confirm the spacing is smaller than the tunnel length.", "Confirm the density is within the range the catalog covers, which runs from four to twelve shots per foot inclusive.", "Confirm the dimensionless spacing falls below ten, which is the upper end of the correlation''s development range."]'::jsonb, 0, 'The error it catches is a factor of about three and a quarter.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which of these would you expect to change if the same gun were run in a different rock?', '["The plane-flow term, through the effective wellbore radius.", "The wellbore blockage term, since the blockage ratio depends on the tunnel length relative to the wellbore radius.", "The converging-flow term, through the permeability anisotropy.", "Nothing at all, because a perforation skin is a geometric quantity and no rock property enters it anywhere."]'::jsonb, 2, 'Anisotropy is the one rock property in the skin calculation, and it enters only that term.'),
  ('perfsand', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What would you want next after a sieve analysis and a gun catalog row?', '["A production forecast for the well.", "A stress and strength profile, which is what the sanding calculation runs on.", "A second sieve analysis from a different depth in the same interval, so that the variability along the interval can be seen.", "The vendor''s charge data sheet for the actual gun, charge and casing combination that will be run on the job."]'::jsonb, 1, 'That profile comes from the Geomechanics course, and the Expert tier consumes it rather than deriving it.'),
  ('perfsand', 'beginner', 'final', null, 1, 'An asset team wants a tool that will tell them how many barrels a new gun will add. Can this course''s engine do that?', '["Yes, once the reservoir pressure has been supplied.", "Yes, provided the permeability and the fluid viscosity are entered alongside the gun and the sieve analysis for the interval.", "No, because it produces a dimensionless skin and a ratio, never a rate.", "No, because the correlation behind it was fitted on concrete targets rather than on the reservoir rock that the well will actually produce from."]'::jsonb, 2, 'Turning a ratio into barrels needs a reservoir model, which sits outside this tool entirely.'),
  ('perfsand', 'beginner', 'final', null, 2, 'Sand has been reported at the separator on a well whose safety valve later failed to close. Which of those two is the integrity problem?', '["The valve, because a barrier that no longer works is a different class of failure.", "The separator, because that is where the sand was seen.", "Neither, because sand at surface is a production nuisance and a valve can always be replaced at the next workover opportunity.", "Both equally, since each of them was caused by the same produced solids arriving from the same failing perforation cavity."]'::jsonb, 0, 'Deferred production costs money. A failed barrier costs a well control margin.'),
  ('perfsand', 'beginner', 'final', null, 3, 'Two mechanisms bring sand to surface. Which one does the Expert tier actually compute?', '["Migration of loose fines with the flowing fluid.", "Erosion of the completion hardware by solids already in the stream, which widens the flow path over time.", "Dissolution of the natural cement between grains by produced water of falling salinity.", "Mechanical failure of the cavity wall."]'::jsonb, 3, 'Fines migration is what the fines percentage warns about, and it is not an onset criterion.'),
  ('perfsand', 'beginner', 'final', null, 4, 'A trainee says perforating and sand control are two separate subjects that happen to be taught together for convenience. Where does that go wrong?', '["Nowhere, since the two use different software.", "The tunnel a charge makes is the same cavity whose wall the sanding calculation is about.", "It understates the case only slightly, because both operations are normally carried out on the same wireline run into the well.", "It is wrong because gravel packs are always perforated with the same gun that made the original completion tunnels."]'::jsonb, 1, 'A gravel pack is placed through those same holes, which is why the two decisions constrain each other.'),
  ('perfsand', 'beginner', 'final', null, 5, 'Which pairing correctly matches a quantity to whether this engine computes it?', '["Both are computed from the sieve analysis.", "Critical flowing pressure is not computed, but the mass of sand produced per cubic metre of fluid over the life of the well is.", "Critical flowing pressure, computed. Sand production rate, not computed.", "Neither is computed, because the engine restricts itself to perforation geometry and never addresses the failure of the cavity."]'::jsonb, 2, 'An onset criterion says when failure starts. It says nothing about how much sand follows.'),
  ('perfsand', 'beginner', 'final', null, 6, 'A junior engineer sends over a template with columns for casing weight, cement sheath thickness, gun standoff and porosity, and asks which of them the skin routine will take. What does it actually want instead?', '["How far the tunnel reaches, how wide it is, how far apart successive shots sit, and the hole size.", "Whatever the charge data sheet happens to print for that gun.", "Exactly the columns on that template, since the routine was built around a standard completion reporting spreadsheet.", "Only the two permeability ratios, because the geometry terms are supplied internally from the casing size entered."]'::jsonb, 0, 'Standoff and shot interval matter physically and still sit outside this model, which names them rather than hiding them.'),
  ('perfsand', 'beginner', 'final', null, 7, 'What is the honest description of what an Associate pass in this course certifies?', '["That you can design a gravel pack unsupervised.", "That you can compute the four skin components and defend the total against an independent check made by a colleague.", "That you can run a sanding onset calculation along an interval and identify the row that governs the completion.", "That you can read a gun catalog and a sieve analysis and say what each one constrains."]'::jsonb, 3, 'The computing tiers come later. The Associate tier is about reading the two inputs correctly.'),
  ('perfsand', 'beginner', 'final', null, 8, 'A vendor sheet quotes 24 inches of penetration. What has to happen before that becomes a tunnel length?', '["Nothing, because the figure is already in field units.", "It must be corrected from the concrete test target to the rock the well is actually in.", "It has to be halved, because published figures are quoted for the deepest charge in the string rather than for a representative one.", "It has to be multiplied by the shot density, since penetration is quoted per shot and the calculation needs the interval total."]'::jsonb, 1, 'An API Section One test fires into a concrete target, which is not the reservoir.'),
  ('perfsand', 'beginner', 'final', null, 9, 'Why can a single shaped charge not be optimised for both a big entrance hole and deep penetration?', '["Because the two are measured in different test sections.", "Because a big entrance hole requires a heavier explosive load, and heavier loads are not permitted inside through-tubing carriers.", "The jet''s energy is finite, so shaping it to spread wide is shaping it not to go deep.", "Because penetration is measured in the rock while entrance hole is measured in the casing, so the two cannot be compared."]'::jsonb, 2, 'Which one you want depends on whether the job is a gravel pack or a natural completion.'),
  ('perfsand', 'beginner', 'final', null, 10, 'A gun is quoted at 6 shots per foot. What does the skin calculation actually use?', '["The spacing between shots in metres, which is the reciprocal of the density.", "The density itself, converted to shots per metre.", "The total number of shots across the perforated interval, which requires the interval length to be supplied as well.", "The density multiplied by the phasing angle, which together give the number of shots in each vertical plane."]'::jsonb, 0, 'That is why the interval length never appears among the seven inputs.'),
  ('perfsand', 'beginner', 'final', null, 11, 'Your team lead assumes the software already scaled the data sheet figure down for confined rock at depth, and wants to know where that adjustment gets logged. What do you tell him?', '["It appears in the provenance string attached to every result.", "It happens silently at the input stage, using the rock strength and the effective stress supplied with the interval.", "It is applied only when the phasing angle is one the published tables carry, and skipped otherwise without comment.", "Nothing scaled it. The published figure is taken as given and any rock adjustment is left to you."]'::jsonb, 3, 'Declining to guess an adjustment the user never supplied is a scope decision, stated so it can be made outside.'),
  ('perfsand', 'beginner', 'final', null, 12, 'Zero phasing means every shot is fired in the same direction. Why is that a special case rather than just another angle?', '["Because the gun cannot be oriented at zero degrees.", "All the tunnels lie in one vertical plane, so they compete with each other for the same flow.", "Because the published tables do not carry a set of constants for it, so the engine has to interpolate between sixty and ninety degrees.", "Because a gun with no phasing has to be run on tubing rather than on wireline, which changes the whole operation."]'::jsonb, 1, 'It gives the smallest effective wellbore radius of any of the tabulated angles.'),
  ('perfsand', 'beginner', 'final', null, 13, 'Somebody types a phasing of 30 degrees into the tool. What happens?', '["It is accepted and rounded to the nearest tabulated angle.", "It is accepted with a warning, and the engine interpolates the tabulated constants linearly between the two neighbouring angles.", "It is refused, because the tables carry constants only for the six published angles.", "It is accepted, because phasing enters the correlation as a continuous variable rather than through a lookup."]'::jsonb, 2, 'Interpolating fitted constants between tabulated angles is not something the published work supports.'),
  ('perfsand', 'beginner', 'final', null, 14, 'A student notices that across the teaching rows the slim through-tubing carriers are all in-line and sparse while the bigger casing carriers are denser and phased. Does that pattern survive a swap to a manufacturer sheet?', '["Yes. Those class relationships follow from carrier size and charge physics, so every vendor sheet shows them.", "No, because each vendor arranges its own classes differently.", "Yes, and so do the tabulated hole sizes and depths, which were sampled from published reports and are quotable.", "Only for the casing classes, because through-tubing hardware is not covered by any comparison standard vendors share."]'::jsonb, 0, 'Substituting a real data sheet changes the numbers in every row and leaves the organising structure untouched.'),
  ('perfsand', 'beginner', 'final', null, 15, 'Convert a shot density of 5 shots per foot into a spacing.', '["About 16 millimetres between shots.", "About 305 millimetres between shots, because a foot is that many millimetres and the shots are counted per foot.", "About 6 millimetres between shots, since five shots per foot is roughly sixteen shots for every metre of interval.", "About 61 millimetres between shots."]'::jsonb, 3, 'One foot divided by the shot count, converted to metres, is the whole of the arithmetic.'),
  ('perfsand', 'beginner', 'final', null, 16, 'A tally is typed in and the tool reports a distance between holes of about 15 millimetres, where roughly 51 was expected. What went wrong, and which one line check would have caught it before the run?', '["The phasing was entered in radians rather than in degrees.", "The conversion was run the wrong way. Distance times density in matching units has to come to one exactly.", "The tunnel length was left at its default, and the tool scales the separation by that length before reporting it.", "Nothing is wrong, because the reported separation is measured along the carrier axis rather than along the casing wall."]'::jsonb, 1, 'A factor of about three and a quarter between feet and metres is the commonest error in this whole subject.'),
  ('perfsand', 'beginner', 'final', null, 17, 'A report says a perforated six inch hole now behaves like a nine inch one, and a colleague objects that nobody widened anything. Settle the argument.', '["The report is wrong, since no radius can exceed the bit size.", "Your colleague is right, because the quoted radius is the outer edge of the damaged shell measured from the axis.", "It is an equivalence, not a measurement. Tunnels past the wall let the well flow as though it were bigger.", "Both are right, because the number is a drilled radius until the tunnels are washed clean and an equivalence after."]'::jsonb, 2, 'Far from the well the flow cannot tell a set of tunnels from a plain cylinder, which is what the comparison uses.'),
  ('perfsand', 'beginner', 'final', null, 18, 'A data sheet lists the shattered shell around each tunnel as three times more permeable than untouched rock, and the tool halts with a named error rather than returning a total. Is halting justified?', '["Yes. Firing a charge cannot improve the rock it wrecks, so that entry describes something that never occurs.", "No, because an acid wash can genuinely improve damaged rock.", "No, because the term would simply come out negative, and a negative contribution is an ordinary arithmetic outcome.", "Only if the shell radius is wrong as well, since the two shell entries are validated together rather than singly."]'::jsonb, 0, 'Letting it through would make a damaged completion read as a stimulated one, which nobody downstream could detect.'),
  ('perfsand', 'beginner', 'final', null, 19, 'The gun is already loaded on the truck, and the breakdown shows the damaged shell contributing more than the other three terms put together. What is still available to you?', '["Nothing at all, since every term is fixed once loading is done.", "Raise the wellbore radius by underreaming, which is the only lever left once the charge selection has already been frozen.", "Change the orientation at the wellsite, because it is set by how the carrier is made up rather than by the charge.", "Fire it underbalanced or wash the tunnels afterwards, since that term is a permeability and can be restored."]'::jsonb, 3, 'Short tunnels at low density make that shell dominate, and it is the one contribution an operation can still remove.'),
  ('perfsand', 'beginner', 'final', null, 20, 'A well has thirty metres of gun on depth but only twelve metres of it is shot. Where does that difference enter the perforation skin the tool hands back?', '["It scales the shot density down by the fraction actually shot.", "Nowhere at all. That geometry sits outside the model and shows up as a separate partial penetration term.", "It enters through the spacing, because unshot footage stretches the average distance between holes across the zone.", "It enters twice, once through the converging term and once through the shell, since both read a length along a well."]'::jsonb, 1, 'A repeating unit cell stands in for the whole zone, so no length along the well ever reaches the calculation.'),
  ('perfsand', 'beginner', 'final', null, 21, 'Moving a job from in-line shots to forty five degree phasing flips the biggest contribution from positive to negative. What has physically changed about the flow?', '["The sign convention reverses as soon as any phasing is applied.", "Nothing physical changed, because that contribution is fitted to tabulated constants rather than to a flow geometry.", "The tunnels now surround the well and reach rock a bare wall never touches, so it drains like a wider one.", "The damaged shell has been shared out between more tunnels, which is what pushes the largest contribution below zero."]'::jsonb, 2, 'Forty five degrees carries the largest tabulated constant, which is why it gives the biggest equivalent radius.'),
  ('perfsand', 'beginner', 'final', null, 22, 'Which sand sample source carries the worst bias, and why?', '["Produced sand, because the well has already sorted it by carrying the fines away.", "A sidewall core, because it is small.", "A conventional core, because the coring fluid invades it and rearranges the grain packing before it reaches the laboratory.", "A bailed sample, because it has been sitting in the rathole where cuttings from higher in the hole accumulate."]'::jsonb, 0, 'The sample a well hands you is the sample the well has already edited.'),
  ('perfsand', 'beginner', 'final', null, 23, 'A sieve table lists D10 as the smallest number in the set. What does that tell you?', '["That the sand is exceptionally well sorted.", "That the sieve stack was too coarse at the fine end, so the smallest fraction was never captured by any of the screens used.", "That the sample was taken from produced sand rather than from a core, which biases every percentile downward.", "It is a passing curve, not a retained one, and the convention must be flipped."]'::jsonb, 3, 'On a retained curve D10 is the coarse end and is therefore the largest of the D-values.'),
  ('perfsand', 'beginner', 'final', null, 24, 'Two sieves a decade apart bracket the median at 40 and 60 percent retained. Where does D50 fall?', '["Exactly halfway between the two sieve openings.", "At the geometric midpoint of the two sieve sizes, not the arithmetic one.", "At the coarser of the two sieve sizes, because the retained convention always reports the sieve that the fraction sat on top of.", "It cannot be determined without knowing the mass retained on every other sieve in the stack as well."]'::jsonb, 1, 'Interpolating on a log scale is what makes the midpoint geometric.'),
  ('perfsand', 'beginner', 'final', null, 25, 'Why does linear interpolation of a D-value err in a particular direction?', '["It understates the size by a fixed five percent.", "It errs either way depending on whether the interpolation is being done above or below the median of the distribution.", "It overstates the size, because a straight line sits above the curve on log axes.", "It does not err at all, provided the two bracketing sieves come from the same standard series."]'::jsonb, 2, 'An overstated grain size sizes gravel coarser than it should be, which is the unsafe direction.'),
  ('perfsand', 'beginner', 'final', null, 26, 'A sieve stack stops at 70 percent retained. What does the engine return for D90?', '["Nothing, because the curve never reaches that percentile.", "The finest sieve size in the stack.", "An extrapolated value, obtained by continuing the trend of the last two points in the stack down to the required percentile.", "Zero, which the downstream calculations then treat as a missing value and skip over silently."]'::jsonb, 0, 'Refusing to extrapolate is the whole point, because the data simply do not go there.'),
  ('perfsand', 'beginner', 'final', null, 27, 'A client asks why the report prints percentiles that none of the sizing formulas ever read, and proposes trimming them to shorten the deliverable. Make the case for keeping them.', '["They are needed if anyone wants to reproduce the sieve weights.", "Each one feeds a different graded field in the capstone, so removing any of them would break the marking scheme.", "The published selection literature demands the full set before any completion type indication may be issued at all.", "They let a reader see the shape of the curve, and a blank one warns that the stack was cut short."]'::jsonb, 3, 'Two percentiles decide, and the others say whether those two describe the sample or merely happen to exist.'),
  ('perfsand', 'beginner', 'final', null, 28, 'A laboratory sheet headed grain counts reports twelve percent in its finest bin. Why should that go back to the laboratory before anything in this workflow reads it?', '["Because a count of grains cannot be plotted on a log size axis.", "Everything here reads a mass split off a weighed stack, and a tally by particle is a different statistic.", "Because bins are conventionally reported as volume fractions, and a count and a volume differ by the packing factor.", "Because a finest bin above ten percent lies outside the range the sieve interpolation was ever developed against."]'::jsonb, 1, 'By count the fine end swamps everything, so one sample looks like a different sand on the wrong basis.'),
  ('perfsand', 'beginner', 'final', null, 29, 'Define the uniformity coefficient as this course uses it.', '["The ratio of D50 to the mean grain size.", "The standard deviation of the grain size distribution divided by its mean, expressed as a percentage of that mean.", "The ratio of the coarse percentile to the fine one, D40 over D90.", "The ratio of the largest grain in the sample to the smallest one that any of the sieves in the stack retained."]'::jsonb, 2, 'It is a spread measure, and a value near one describes a sand of nearly a single size.'),
  ('perfsand', 'beginner', 'final', null, 30, 'A slot window is quoted at one to two times the coarse decile, which is wider than nearly every grain it has to hold back. Why does the sand stay put?', '["Coarse grains arch across the gap and wedge together, and that arch then traps the finer material behind it.", "The grains are simply too large to pass through the slot at all.", "A cake of fine material builds on the outside of the slot and does the filtering, while the slot merely supports it.", "Velocity through the slot is low enough that grains settle out under gravity before they can ever reach the opening."]'::jsonb, 0, 'An opening several grain diameters across still holds sand back, which is why a slot can be sized that way at all.'),
  ('perfsand', 'beginner', 'final', null, 31, 'Two wells run the same standalone completion. One sand has a middle spread ratio near 1.5, the other near seven, and only the second keeps making solids for years. Explain the difference.', '["The second sand is simply finer overall than the first one is.", "The second sand cannot form a stable arch at all, so nothing is held back and the hardware behaves as bare pipe.", "The gauge on the second well was sized on its finest grain, which throttles the flow and drags solids through with it.", "A wide spread leaves plenty of material fine enough to travel through the arches, so the bridge always leaks."]'::jsonb, 3, 'The arch forms in both cases. In the badly graded sand the tail simply walks through it and keeps going.'),
  ('perfsand', 'beginner', 'final', null, 32, 'A geologist argues that a grain at forty three microns behaves no differently from one at forty five, so the boundary the tool uses is arbitrary. Is she right, and does it matter?', '["She is wrong, because clay begins to swell exactly at that size.", "She is right that it is a convention, and it still matters because every standard stack carries that screen.", "She is right and it therefore does not matter, since any nearby size would move the ladder rungs by the same amount.", "She is wrong, because the boundary marks where a bridge stops forming and material begins entering the pack instead."]'::jsonb, 1, 'A number was needed and that screen sits in every stack, which is what makes an arbitrary line a workable one.'),
  ('perfsand', 'beginner', 'final', null, 33, 'Two pans come off the stack weighing the same, but one holds grains about a tenth the diameter of the other. Which pan holds more particles, and why does a pack care?', '["Neither, since equal weights must mean equal particle numbers.", "The coarser pan, because larger grains pack less efficiently and therefore occupy more of the pan for equal weight.", "The finer pan, by roughly a thousand to one, and it is the particle tally that finds the pore throats.", "The finer pan, by about ten to one, and no pack cares because anything that small passes straight through it anyway."]'::jsonb, 2, 'Mass goes as the cube of the diameter, so a small weight fraction at the fine end is an enormous population.'),
  ('perfsand', 'beginner', 'final', null, 34, 'A summary sheet prints one spread ratio near two for a sample and a second, taken over a much wider span of the same curve, near nine. A colleague calls that a typing error. Is it?', '["No. It says the sample has tails that the middle of the curve cannot see, so read the fine end closely.", "Yes, since two measures of spread on one sample must agree.", "No, and it shows the two figures came from different splits of the sample, which is a handling error in the laboratory.", "Yes, because the wider span contains the narrower one and so cannot possibly return the larger of the two numbers."]'::jsonb, 0, 'The wide span is dominated by the tails and the narrow one is not, so a gap between them is information.'),
  ('perfsand', 'beginner', 'final', null, 35, 'One coarse sand and one fine sand are both well graded and clean, and the advisor hands back the identical completion type for both. A drilling engineer files that as a bug. Is it?', '["Yes, since coarse and fine sands need different hardware.", "Yes, because the advisor should read three figures, and the third of them is precisely the median it has ignored here.", "No, because hardware can only be manufactured at a single slot width, so grain size cannot influence the choice.", "No. Median size sets how coarse the gravel has to be, and it has no say in which completion gets picked."]'::jsonb, 3, 'Shape of the distribution decides the type. How coarse the hardware must be is a separate question asked later.'),
  ('perfsand', 'beginner', 'final', null, 36, 'A design basis puts a sand comfortably inside the well graded band but carrying just over one part in twelve finer than the cutoff, and proposes a slotted standalone completion. Write your review comment.', '["Approve it, since slotted pipe is tolerant of fine material.", "Good grading cannot rescue that much fine material, so the ladder puts this well on a gravel rung.", "Ask for the median first, because a standalone completion can be sized for any sand once the slot width is chosen well.", "Approve it provided the wider span ratio is also low, because grading at the tails offsets a high fine fraction."]'::jsonb, 1, 'Fine content decides the middle rungs of the ladder, and one part in twelve is well past where it steps down.'),
  ('perfsand', 'beginner', 'final', null, 37, 'A pack sizing request arrives with the median grain size and nothing else, and the sender apologises for not attaching the full table. Was anything actually missing?', '["Yes, the fine content and the spread ratio are both needed.", "Yes, the whole table, because the multiplier depends on the shape of the distribution rather than on one percentile.", "No. Saucier multiplies that one percentile, though whether a sand is sold in the resulting window is separate.", "Yes, the chosen screen gauge, because the pack has to bridge on the hardware as well as against the formation sand."]'::jsonb, 2, 'The band is narrow enough that a real sand can miss it entirely, which is a separate problem from sizing it.'),
  ('perfsand', 'beginner', 'final', null, 38, 'You have ninety seconds with a nine row sheet and must flag the entries most likely to hurt a well. Which column do you read first, and what are you looking for?', '["The angle between successive shots, looking for the in-line rows where the positive totals all sit.", "The carrier diameter, looking for the slimmest hardware there.", "The depth column, looking for short tunnels, because a tunnel that fails to clear the damaged rock cannot help.", "The hole size column, looking for the small entrances, since a narrow entrance throttles everything behind it anyway."]'::jsonb, 0, 'Orientation is the single biggest lever on that sheet, and the next tier puts a number on how big it is.'),
  ('perfsand', 'beginner', 'final', null, 39, 'A laboratory stack bottoms out at ninety microns, well above the cutoff, and a colleague still wants a completion type out of it. What can be delivered and what cannot?', '["Nothing at all, because the analysis is unusable as it stands.", "Everything, provided the two finest points are projected downward along the slope of the fine end of the measured curve.", "The fine content but not the gravel size, since the median falls below the finest screen the laboratory ran.", "A gravel size can be taken from the median, but the fraction below the cutoff was never actually weighed."]'::jsonb, 3, 'The advisor needs both ladder inputs, so a missing fine fraction stops it rather than letting it guess a rung.'),
  ('perfsand', 'beginner', 'final', null, 40, 'The same gun is run in a different rock. Which output changes?', '["The phasing angle of the gun as run.", "The tunnel length, because the concrete-to-rock correction changes with the rock.", "The shot density, since a harder formation absorbs more of the charge energy and fewer of the shots penetrate the casing cleanly.", "The wellbore radius, which is set by the bit size used to drill through the producing interval."]'::jsonb, 1, 'The catalog row is unchanged. What the rock does to the penetration is not.'),
  ('perfsand', 'beginner', 'final', null, 41, 'A tender response cites a figure of thirty inches from this course''s teaching sheet as the tunnel the offered charge will make. What is the objection?', '["None at all, as long as the source is cited in a footnote.", "Only the units, since a tender response would normally be expected to state the figure in millimetres rather than inches.", "That figure was invented to teach a method and belongs to no charge that any manufacturer actually sells.", "That the concrete correction has not been applied yet, after which the figure becomes a legitimate tender input."]'::jsonb, 2, 'The structure of the sheet transfers to any vendor. The numbers printed on it describe no gun in the world.'),
  ('perfsand', 'beginner', 'final', null, 42, 'What single idea holds both halves of the Associate tier together?', '["A perforation is a cavity, and both halves of the course are about that cavity.", "Both halves are computed by the same engine.", "Both halves reduce to a grain size distribution, which is the only measurement either of them genuinely requires as an input.", "Both halves are decided by the shot density, which sets the flow geometry and the spacing of the failure planes alike."]'::jsonb, 0, 'One half asks what flows through it and the other asks whether its wall holds.');
